function advanceCreature(e,dt){if(e.id===possessed)return;const m=motionFor(e),dx=e.tx-e.x,dy=e.ty-e.y,d=Math.hypot(dx,dy);if(d<.035){e.tx=e.x;e.ty=e.y;m.vx=m.vy=0;return;}const pace=(e.kind==='wolf'?1.7:e.kind==='sheep'?.9:1.2)*m.pace*(e.energy<25?.7:1)*(e.traits?.includes('swift')?1.15:1)*(typeof mindFor==='function'&&e.talent==='swift'?1.25:1)*(typeof mindFor==='function'&&grid[idx(e.x,e.y)].road?1.35:1)*Math.min(1,d/.4),blend=1-Math.exp(-dt*8);m.vx+=(dx/d*pace-m.vx)*blend;m.vy+=(dy/d*pace-m.vy)*blend;let sx=m.vx*dt,sy=m.vy*dt;if(Math.hypot(sx,sy)>d){const scale=d/Math.hypot(sx,sy);sx*=scale;sy*=scale;}const pass=(x,y)=>(walkable(x,y)||(e.sailing&&inside(x,y)&&grid[idx(x,y)].t===0))&&(typeof animalPositionClear!=='function'||animalPositionClear(e,x,y));const x=e.x+sx,y=e.y+sy;if(pass(x,y)){e.x=x;e.y=y;m.steps+=Math.hypot(sx,sy);}else if(pass(x,e.y)){e.x=x;m.vy=0;m.steps+=Math.abs(sx);}else if(pass(e.x,y)){e.y=y;m.vx=0;m.steps+=Math.abs(sy);}else{m.vx=m.vy=0;e.tx=e.x;e.ty=e.y;}}
