function pathStep(e,goal,allowWater){if(!inside(e.x,e.y)||!inside(goal.x,goal.y))return null;const start=idx(e.x,e.y),end=idx(goal.x,goal.y);if(start===end)return null;const pass=i=>grid[i].t!==4&&(allowWater||grid[i].t!==0);if(!pass(end))return null;const key=terrainEpoch+':'+end+':'+Number(allowWater);let cached=routeFields.get(key);if(!cached||simTime-cached.time>8){const distance=new Int16Array(N).fill(-1),queue=new Int32Array(N);let head=0,tail=1;queue[0]=end;distance[end]=0;while(head<tail){const i=queue[head++],x=i%W,y=Math.floor(i/W);for(const n of [x>0?i-1:-1,x<W-1?i+1:-1,y>0?i-W:-1,y<H-1?i+W:-1])if(n>=0&&distance[n]===-1&&pass(n)){distance[n]=distance[i]+1;queue[tail++]=n;}}cached={distance,time:simTime};if(routeFields.size>=48)routeFields.delete(routeFields.keys().next().value);routeFields.set(key,cached);routeBuilds++;}else routeHits++;if(cached.distance[start]<0)return null;const x=start%W,y=Math.floor(start/W),neighbors=[x>0?start-1:-1,x<W-1?start+1:-1,y>0?start-W:-1,y<H-1?start+W:-1];const next=neighbors.find(n=>n>=0&&pass(n)&&cached.distance[n]>=0&&cached.distance[n]<cached.distance[start]);return next===undefined?null:{x:next%W+.5,y:Math.floor(next/W)+.5};}
moveTarget=function(e,x,y){if(e.id===possessed)return;const m=motionFor(e);if(e.kind==='wolf'&&Math.hypot(x-e.x,y-e.y)<1.2){e.tx=e.x;e.ty=e.y;return;}if(e.kind!=='wolf'&&e.hunger>65){if(simTime<m.waitUntil)return;if(Math.hypot(e.tx-e.x,e.ty-e.y)<.08&&m.walking){m.waitUntil=simTime+.6+(e.id%7)*.25;m.walking=false;return;}};if(e.kind!=='wolf'&&e.hunger>65&&Math.hypot(e.tx-e.x,e.ty-e.y)>.25)return;if(!walkable(x,y))return;const len=Math.hypot(x-e.x,y-e.y);let clear=true;for(let k=1;k<=Math.ceil(len*2);k++){const t=k/Math.max(1,Math.ceil(len*2));if(!walkable(e.x+(x-e.x)*t,e.y+(y-e.y)*t)){clear=false;break;}}const target=clear?{x,y}:pathStep(e,{x,y},false);if(target){m.walking=true;e.tx=target.x;e.ty=target.y;}};
function routineStep(dt){const alive=new Set(entities.map(e=>e.id));for(const cache of [visualPositions,miningGoals,workerGoals])for(const id of cache.keys())if(!alive.has(id))cache.delete(id);const hour=readCalendar().hour;for(const e of humans()){ensureRoutine(e);if(e.id===possessed){e.activity='controlled';continue;}if(e.soldier){e.activity='defending';continue;}const v=villages.find(v=>v.id===e.village),home=houses.filter(h=>h.village===e.village).sort((a,b)=>Math.hypot(a.x-e.x,a.y-e.y)-Math.hypot(b.x-e.x,b.y-e.y))[0];e.activity=hour>=21||hour<6?'sleeping':hour>=18||e.energy<12?'resting':'working';if(e.activity==='working')e.energy=Math.max(0,e.energy-dt*.05);else if(typeof isResidentIndoors!=='function')e.energy=Math.min(100,e.energy+dt*(e.activity==='sleeping'?.12:.08));if(typeof mindFor!=='function'&&e.activity!=='working'&&home){if(Math.hypot(e.x-home.x,e.y-home.y)>1.2){const next=pathStep(e,home,false);if(next){e.tx=next.x;e.ty=next.y;}}else{e.tx=e.x;e.ty=e.y;e.hp=Math.min(100,e.hp+dt*.01);}}if(v&&e.hunger<55&&v.food>=2&&(typeof mindFor!=='function'||Math.hypot(e.x-v.x,e.y-v.y)<3)){v.food-=2;e.hunger=Math.min(100,e.hunger+22);}}}
function steerWorkers(){for(const e of humans()){if(e.id===possessed)continue;const v=villages.find(v=>v.id===e.village);if(e.soldier){const enemy=humans().filter(p=>atWar(kingdomOf(e),kingdomOf(p))).sort((a,b)=>Math.hypot(a.x-e.x,a.y-e.y)-Math.hypot(b.x-e.x,b.y-e.y))[0];if(enemy&&Math.hypot(enemy.x-e.x,enemy.y-e.y)>1.5){const next=pathStep(e,enemy,v?.tech>=2);if(next){e.tx=next.x;e.ty=next.y;e.sailing=grid[idx(next.x,next.y)].t===0;}}continue;}if(!v||!isOnDuty(e)||e.age<2||e.hunger<40)continue;if(e.job==='miner'){miningStep(e,v,0);continue;}if(!['farmer','lumberjack'].includes(e.job))continue;const current=grid[idx(e.x,e.y)],wanted=t=>e.job==='lumberjack'?t.t===3:t.t===5;if(wanted(current)){e.tx=e.x;e.ty=e.y;continue;}const prior=workerGoals.get(e.id);let target=prior&&prior.epoch===terrainEpoch&&simTime-prior.time<8&&wanted(grid[idx(prior.goal.x,prior.goal.y)])?prior.goal:null,best=Infinity;if(!target)for(let y=Math.max(0,Math.floor(v.y-12));y<Math.min(H,v.y+12);y++)for(let x=Math.max(0,Math.floor(v.x-12));x<Math.min(W,v.x+12);x++)if(wanted(grid[idx(x,y)])){const d=Math.hypot(x+.5-e.x,y+.5-e.y);if(d<best){best=d;target={x:x+.5,y:y+.5};}}if(target){workerGoals.set(e.id,{goal:target,time:simTime,epoch:terrainEpoch});const next=pathStep(e,target,false);if(next){e.tx=next.x;e.ty=next.y;}}}}
