function paintCachedMap(){if(!scenery){scenery=document.createElement('canvas');scenery.width=W*16;scenery.height=H*16;sceneryContext=scenery.getContext('2d');}const state=Number(spriteReady)+':'+Number(economySpriteReady);if(state!==mapSpriteState){mapSpriteState=state;mapDirty=true;}if(mapDirty){const c=sceneryContext;c.setTransform(16,0,0,16,0,0);c.clearRect(0,0,W,H);c.imageSmoothingEnabled=false;burningTiles=[];for(let y=0;y<H;y++)for(let x=0;x<W;x++){const t=grid[idx(x,y)];c.fillStyle=typeof terrainColorAt==='function'?terrainColorAt(x,y,t):colors[t.t];c.fillRect(x,y,1.04,1.04);if(t.t===0){if(t.shade>.79){c.fillStyle='#21516b';c.fillRect(x+.15,y+.55,.45,.1);}if([[1,0],[-1,0],[0,1],[0,-1]].some(([dx,dy])=>inside(x+dx,y+dy)&&grid[idx(x+dx,y+dy)].t!==0)){c.fillStyle='#3385a0';c.fillRect(x,y,1.04,1.04);}}else if(t.shade>.62){c.fillStyle=t.t===2?'#ead19655':'#b0d88925';c.fillRect(x+.2,y+.2,.2,.2);}}for(let y=0;y<H;y++)for(let x=0;x<W;x++){const t=grid[idx(x,y)];if(typeof paintDepthWorld!=='function'&&spriteReady&&t.obj>=0&&!(typeof animatedScenery==='function'&&animatedScenery(x,y,t))&&!(typeof paintBiomeObject==='function'&&paintBiomeObject(c,x,y,t)))atlasTo(c,sprite,t.obj,4,x+.5,y+.65,t.obj===2?2.8:t.obj===11?1.8:t.obj===3?1.4:2.25);if(t.road){c.fillStyle='#bca77788';c.fillRect(x+.25,y+.3,.5,.4);}if(typeof paintDepthWorld!=='function'&&economySpriteReady&&t.ore?.amount>0)atlasTo(c,economySprite,oreSprites[t.ore.type],4,x+.5,y+.5,1.65);if(t.fire>0)burningTiles.push(idx(x,y));}if(typeof paintEraScenery==='function')paintEraScenery(c);mapDirty=false;}ctx.drawImage(scenery,0,0,scenery.width,scenery.height,0,0,W,H);return true;}
