showSelection=function(id){if(document.activeElement?.tagName==='SELECT'&&document.activeElement.closest?.('#selection'))return;rtOld.showSelection(id);const e=humans().find(e=>e.id===id);if(!e)return;ensureRoutine(e);const p=document.createElement('p');p.textContent=({working:'Đang làm việc',sleeping:'Đang ngủ',resting:'Đang nghỉ',defending:'Đang phòng thủ',controlled:'Bạn đang điều khiển'})[e.activity]+' · Thể lực '+Math.round(e.energy)+'%';const label=document.createElement('label');label.textContent='Nghề nghiệp';const select=document.createElement('select');select.setAttribute('aria-label','Đổi nghề cư dân');for(const [job,name] of Object.entries(jobNames)){const o=document.createElement('option');o.value=job;o.textContent=name;select.append(o);}select.value=e.job;select.onchange=()=>{try{setResidentJob(e.id,select.value);}catch(error){toast(error.message);if(!humans().some(p=>p.id===e.id))$('selection').hidden=true;}};label.append(select);$('selection').append(p,label);};
